def can_jump(nums):
    reach = 0
    for index, step in enumerate(nums):
        if index > reach:
            return False
        if index + step > reach:
            reach = index + step
    return True

print(can_jump([2, 3, 1, 1, 4]))
print(can_jump([3, 2, 1, 0, 4]))
print(can_jump([]))
print(can_jump([0]))
